def task_func(input_file="data.json"):
    # Load the data from the JSON file
        with open(input_file, "r") as f:
            data = json.load(f)

        # Initialize an empty dictionary to hold the means and medians
        stats_dict = defaultdict(list)

        # Iterate over each item in the data
        for item in data:
            for k, v in item.items():
                if isinstance(v, dict):
                    for sub_k, sub_v in v.items():
                        stats_dict[k].append(sub_v)
                else:
                    stats_dict[k].append(v)

        # Convert lists to arrays
        stats_array = {k: np.array(stats_dict[k]) for k in stats_dict}

        # Calculate mean and median for numeric keys
        for k in stats_array.keys():
            if all(isinstance(x, (int, float)) for x in stats_array[k]):
                stats_array[k] = [np.mean(stats_array[k]), np.median(stats_array[k])]
            elif any(np.isnan(x) for x in stats_array[k]):
                stats_array[k] = ["N/A", "N/A"]

        # Create DataFrame
        df = pd.DataFrame.from_dict(stats_array, orient='index', columns=['mean', 'median'])

        return df

